  const rule=a.rule||{},now=new Date(),nowIso=now.toISOString(),todayParts=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:rule.timezone||S.profile.timezone||"UTC",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(now).filter(x=>x.type!=="literal").map(x=>[x.type,x.value])),today=todayParts.year+"-"+todayParts.month+"-"+todayParts.day;
